  "checks": [
    {
      "id": "registered-monotonic-deadline-independent-of-timer-scheduling",
      "result": "PASS",
      "rationale": "Deadline is based on performance.now at timer registration. The exit callback compares its observed monotonic timestamp against that deadline before clearing the timer; equality and lateness set both timedOut and lateExitInvalid. This closes the original V1 callback-order gap without increasing the240000ms budget.",
      "evidence": [
        {
          "file": "C:\\Users\\Admin\\.codex\\worktrees\\html-guide-acceptance\\reviewer\\corrections\\0-1-20\\technical-lifecycle-draft-v2\\capture-lifecycle-draft.mjs",
          "sha256": "947cb0a958932d8007b7d3d6efb62c0969ba792272f0c7eaf00c118857fbd6eb",
          "lineStart": 9,
          "lineEnd": 15,
          "excerpt": "  const timerRegisteredMonotonicMs=performance.now(),deadlineMonotonicMs=timerRegisteredMonotonicMs+timeoutMs;\n  const timer=setTimeout(()=>{\n   timedOut=true;const firedMonotonicMs=performance.now();\n   deadlineCallback={firedUtc:new Date().toISOString(),firedMonotonicMs,firedElapsedMs:elapsedMs(),exitAlreadyObserved:!!exit,killAttempted:false,killReturned:null,killError:null};\n   // Never attempt termination against an already observed exited child.\n   if(!exit){deadlineCallback.killAttempted=true;try{deadlineCallback.killReturned=child.kill();}catch(e){deadlineCallback.killError=String(e.message);}}\n  },timeoutMs);"
        },
        {
          "file": "C:\\Users\\Admin\\.codex\\worktrees\\html-guide-acceptance\\reviewer\\corrections\\0-1-20\\technical-lifecycle-draft-v2\\capture-lifecycle-draft.mjs",
          "sha256": "947cb0a958932d8007b7d3d6efb62c0969ba792272f0c7eaf00c118857fbd6eb",
          "lineStart": 19,
          "lineEnd": 25,
          "excerpt": "  child.on('exit',(code,signal)=>{\n   const observedMonotonicMs=performance.now();\n   exit={code,signal,utc:new Date().toISOString(),elapsedMs:elapsedMs(),observedMonotonicMs,inDeadline:observedMonotonicMs<deadlineMonotonicMs};\n   // This independent monotonic check survives delayed/out-of-order timer callbacks.\n   if(!exit.inDeadline){lateExitInvalid=true;timedOut=true;}\n   clearTimeout(timer);\n  });"
        }
      ]
    },
    {
      "id": "genuine-exit-and-complete-stdio-are-separate",
      "result": "PASS",
      "rationale": "Actual process exit code/signal/time and actual close code/signal/time are recorded separately; status comes only from observed exit and is null without exit. Full stdout/stderr and onChunk are collected through close; exit/close mismatch records an error. SDK completion is never consulted as a substitute for exit.",
      "evidence": [
        {
          "file": "C:\\Users\\Admin\\.codex\\worktrees\\html-guide-acceptance\\reviewer\\corrections\\0-1-20\\technical-lifecycle-draft-v2\\capture-lifecycle-draft.mjs",
          "sha256": "947cb0a958932d8007b7d3d6efb62c0969ba792272f0c7eaf00c118857fbd6eb",
